// ── Look up the Brevo API key and build the campaigns-list query string ──
// "period" comes from the Whizz Reports page's month selector: either "all"
// (default — most recent 10 sent campaigns) or "YYYY-MM" (that calendar
// month's campaigns via Brevo's startDate/endDate filters).
//
// Brevo requires startDate/endDate as full ISO-8601 UTC date-TIMEs
// (YYYY-MM-DDTHH:mm:ss.SSSZ), not plain dates — a plain YYYY-MM-DD is
// silently ignored, which is why the date filter previously had no effect.
// endDate also must never be in the future, which matters for the current
// (in-progress) month, so it's clamped to "now" when the month isn't over yet.
const rows = $input.all();
const row = rows.find(r => (r.json.service || '').toLowerCase() === 'brevo');
let cfg = {};
try { cfg = row ? JSON.parse(row.json.data || '{}') : {}; } catch (e) { cfg = {}; }

const query = $('Webhook').first().json.query || {};
const period = query.period;

const params = new URLSearchParams();
params.set('statistics', 'globalStats');
params.set('sort', 'desc');
params.set('status', 'sent');

if (period && period !== 'all') {
  const [y, m] = period.split('-').map(Number);
  const start = new Date(Date.UTC(y, m - 1, 1, 0, 0, 0, 0));
  let end = new Date(Date.UTC(y, m, 0, 23, 59, 59, 999));
  const now = new Date();
  if (end > now) end = now;
  if (start > now) {
    // Selected month hasn't started yet (shouldn't happen from the UI's own
    // month list, but guard against it rather than send an invalid range).
    params.set('limit', '0');
  } else {
    params.set('startDate', start.toISOString());
    params.set('endDate', end.toISOString());
    params.set('limit', '50');
  }
} else {
  params.set('limit', '10');
}

return [{ json: { apiKey: cfg.apiKey || '', listId: cfg.listId || '', skip: !cfg.apiKey, queryString: params.toString() } }];

// ── Normalize Brevo's campaign list + globalStats, plus the total contact count for the ──
// configured list, into the shape the Reports page expects.
// "Total Email Leads" = Brevo's own count of contacts in your configured list (all-time,
// not period-scoped — a contact list doesn't have a clean "added this month" concept here).
// The list-count call degrades to 0 rather than erroring if no list is configured, or if
// Brevo returns something unexpected (e.g. "count" missing) — never block the campaigns data.
const campaignsResp = $('Fetch Brevo Campaigns').first().json;
const campaigns = (campaignsResp.campaigns || []).map(c => {
  const stats = c.statistics && c.statistics.globalStats ? c.statistics.globalStats : {};
  return {
    name: c.name || c.subject || 'Untitled Campaign',
    sentDate: c.sentDate || c.scheduledAt || null,
    sent: stats.sent || 0,
    delivered: stats.delivered || 0,
    opens: stats.uniqueViews || stats.opens || 0,
    clicks: stats.uniqueClicks || stats.clicks || 0,
    bounces: (stats.softBounces || 0) + (stats.hardBounces || 0)
  };
});

const listResp = $input.first().json;
const totalEmailLeads = typeof listResp.count === 'number' ? listResp.count : 0;

return [{ json: { campaigns, totalEmailLeads } }];
